package bottlesong

import "fmt"

var bottleNumbers = map[int]string{
	0:  "no",
	1:  "one",
	2:  "two",
	3:  "three",
	4:  "four",
	5:  "five",
	6:  "six",
	7:  "seven",
	8:  "eight",
	9:  "nine",
	10: "ten",
}

func Recite(startBottles, takeDown int) []string {
	var verses []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		verses = append(verses,
			fmt.Sprintf("%s green bottles hanging on the wall,", title(bottleNumbers[n])),
			fmt.Sprintf("%s green bottles hanging on the wall,", title(bottleNumbers[n])),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green bottle%s hanging on the wall.", bottleNumbers[n-1], plural(n-1)),
		)
		if n > startBottles-takeDown {
			verses = append(verses, "")
		}
	}
	return verses
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func title(s string) string {
	if s == "" {
		return s
	}
	return fmt.Sprintf("%c%s", uppercase(s[0]), s[1:])
}

func uppercase(c byte) byte {
	if c >= 'a' && c <= 'z' {
		return c - 'a' + 'A'
	}
	return c
}

